function driveSimTicks(
  shard: ReturnType<GalaxyRouter["get"]>,
  ticks: number,
): void {
  const hooks = (shard!.sim as unknown as { hooks: { clock: () => number } }).hooks;
  const originalClock = hooks.clock;
  const startNow = originalClock ? originalClock() : Date.now();
  let now = startNow;
  hooks.clock = () => now;
  try {
    // Prime the loop so the first manual `tick()` doesn't try to
    // step with zero elapsed.
    shard!.sim.tick();
    for (let i = 0; i < ticks; i++) {
      now += 50;
      shard!.sim.tick();
    }
  } finally {
    hooks.clock = originalClock;
  }
}

